<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\ClassService;require_role('SUPER_ADMIN');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{ClassService::review((int)$_POST['class_id'],(string)$_POST['decision'],trim($_POST['notes']??''),(int)current_user()['UserID']);set_flash('success','Class review saved.');redirect('admin/classes.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$rows=db_all("SELECT c.*,t.Name TrainerName,(SELECT COUNT(*) FROM ENROLLMENT e WHERE e.ClassID=c.ClassID AND e.Status='ENROLLED') Enrolled FROM CLASS c LEFT JOIN TRAINER t ON t.TrainerID=c.TrainerID ORDER BY FIELD(c.Status,'PENDING_APPROVAL','SCHEDULED','DRAFT','REJECTED'),c.DateOfClass");$pageTitle='Class review';$pageSubtitle='Approve trainer-created schedules';include ROOT_PATH.'/includes/header.php';?>
<?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Class</th><th scope="col">Trainer</th><th scope="col">Schedule</th><th scope="col">Capacity</th><th scope="col">Status</th><th scope="col">Review</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['ClassName'])?></strong><br><small><?=e($r['Specialization'])?></small></td><td><?=e($r['TrainerName']??'Unassigned')?></td><td><?=e($r['DateOfClass'])?> <?=e(substr($r['StartTime'],0,5))?>–<?=e(substr($r['EndTime'],0,5))?></td><td><?=$r['Enrolled']?> / <?=min(10,(int)$r['Capacity'])?></td><td><span class="badge <?=e($r['Status']==='SCHEDULED'?'badge-green':'badge-amber')?>"><?=e($r['Status'])?></span></td><td><?php if($r['Status']==='PENDING_APPROVAL'):?><form method="post" class="inline-decision"><?=csrf_field()?><input type="hidden" name="class_id" value="<?=$r['ClassID']?>"><input name="notes" aria-label="Review notes" placeholder="Optional notes"><button class="btn btn-success btn-sm" name="decision" value="SCHEDULED">Approve</button><button class="btn btn-danger btn-sm" name="decision" value="REJECTED">Reject</button></form><?php else:?><?=e($r['ReviewNotes']??'—')?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php include ROOT_PATH.'/includes/footer.php';?>
